 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc, color))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            pieces.append(cells)

    # All objects slide to the right, stopping at the edge or another object.
    pieces.sort(key=lambda p: max(c for _, c, _ in p), reverse=True)
    settled = []
    for piece in pieces:
        shift = 0
        while True:
            occupied = {(r, c) for other in settled for r, c, _ in other}
            occupied.update((r, c) for r, c, _ in piece)
            if any(c + 1 >= w or (r, c + 1) in occupied for r, c, _ in piece):
                break
            piece = [(r, c + 1, color) for r, c, color in piece]
            shift += 1
        settled.append(piece)

    out = [[0 for _ in range(w)] for _ in range(h)]
    for piece in settled:
        for r, c, color in piece:
            out[r][c] = color
    return out
